def to_arabic(roman):
    val = {'I':1, 'V':5, 'X':10, 'L':50, 'C':100, 'D':500, 'M':1000}
    result = 0
    i = 0
    while i < len(roman):
        if i + 1 < len(roman) and val[roman[i]] < val[roman[i+1]]:
            result += val[roman[i+1]] - val[roman[i]]
            i += 2
        else:
            result += val[roman[i]]
            i += 1
    return result

def to_roman(n):
    result = ''
    vals = [('M',1000),('CM',900),('D',500),('CD',400),('C',100),('XC',90),('L',50),('XL',40),('X',10),('IX',9),('V',5),('IV',4),('I',1)]
    for sym, v in vals:
        while n >= v:
            result += sym
            n -= v
    return result

# Only 3-character strings that are palindromes
print('Three-letter Roman numeral palindromes (len = 3):')
results = []
for combo in 'IVXLCDM':
    for middle in 'IVXLCDM':
        s = combo + middle + combo  # ABA palindrome, 3 chars
        arabic = to_arabic(s)
        standard = to_roman(arabic)
        if standard == s:
            results.append((s, arabic))
            print(f'{s} = {arabic}')

print(f'\\nSum = {sum(v for _,v in results)}')
